import './continent-icon.css'

/** Two SVG paths in a 64 × 44 box: the world, and the Continent on top of it. */
interface ContinentIconPaths {
  world: string
  land: string
}

// Generated by scripts/build-map-data.mjs. A chunk of its own, so the app's
// main bundle stays small; it loads while the Countries do.
const iconPaths = import('./continent-icons.json').then(
  (module) => module.default as Record<string, ContinentIconPaths>,
)

/**
 * A small map of a Continent, which has no Flag of its own: the world in
 * grey with the Continent in blue when `chosen`, darker grey otherwise.
 * Toggle `continent-icon--chosen` to change it later. Until the maps have
 * loaded (only right after the app starts), it is an empty tile.
 */
export function createContinentIcon(continentId: string, chosen = false): HTMLElement {
  const icon = document.createElement('span')
  icon.className = 'continent-icon'
  icon.classList.toggle('continent-icon--chosen', chosen)
  void iconPaths.then((icons) => {
    const paths = icons[continentId]
    if (!paths) return
    icon.innerHTML =
      '<svg viewBox="0 0 64 44" aria-hidden="true">' +
      `<path class="continent-icon__world" d="${paths.world}" />` +
      `<path class="continent-icon__land" d="${paths.land}" />` +
      '</svg>'
  })
  return icon
}
